import { Table, StringColumn, ReferenceColumn, BooleanColumn } from '../../db'

export const sys_user_preference = Table({
    actions: ['read', 'create'],
    allowWebServiceAccess: true,
    attributes: {
        forcePrimaryKeyOrdering: true,
        no_labels: true,
    },
    label: 'User Preference',
    name: 'sys_user_preference',
    schema: {
        description: StringColumn({
            label: 'Description',
            maxLength: 100,
        }),

        user: ReferenceColumn({
            cascadeRule: 'cascade',
            label: 'User',
            referenceTable: 'sys_user',
        }),

        system: BooleanColumn({
            default: false,
            label: 'System',
        }),
        type: StringColumn({
            default: 'string',
            choices: {
                boolean: {
                    label: 'true | false',
                },
                integer: {
                    label: 'integer',
                },
                reference: {
                    label: 'reference',
                },
                string: {
                    label: 'string',
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Type',
        }),

        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),

        value: StringColumn({
            label: 'Value',
            maxLength: 65000,
        }),
    },
})
